    /// <summary>
    /// Returns information about the topic in a channel direct messages chat administered by the current user
    /// </summary>
    public Task<TdLib.TdApi.Objects.DirectMessagesChatTopic> GetDirectMessagesChatTopicAsync(long chatId = default, long topicId = default)
    {

           using var activity =  StartCallActivity("GetDirectMessagesChatTopicAsync", typeof(GetDirectMessagesChatTopic).FullName ?? "GetDirectMessagesChatTopicAsync");

           try
           {
             return client.GetDirectMessagesChatTopicAsync(chatId, topicId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
